            $oldStock=(int)($lockedRow['stock']??0);if($stock!==$oldStock)inventory_record_movement($pdo,$productId,$variantId,$oldStock===0&&$stock>0?'opening':'adjustment',$stock-$oldStock,$stock,$cost,'variant',$variantId,$oldStock===0?'موجودی اولیه مدل':'اصلاح از صفحه مدل',(int)admin_user()['id']);sync_product_variant_summary($pdo,$productId);$newValue=$cost*$stock;accounting_inventory_adjustment($pdo,$productId,$oldValue,$newValue,(int)admin_user()['id']);product_alert_wake_for_product($pdo,$productId,$variantId);$pdo->commit();if($newUpload!==''&&$lockedRow&&!empty($lockedRow['image_path'])&&$lockedRow['image_path']!==$newUpload)delete_managed_upload((string)$lockedRow['image_path']);flash('success','متغیر محصول ذخیره شد.');redirect(app_url('admin/product-variants.php?product_id='.$productId));
        }
